  str_n25_idol_y_lesson_3 = "การฝึกอบรมพิเศษ: ศิลปะพื้นบ้าน Courier",
  str_n25_idol_y_lesson_4 = "ศิลปะบัลเลต์ ชั้นประถมศึกษาปีที่ 10",
  str_n25_idol_y_lesson_5 = "การฝึกพิเศษ: ศิลปะการต่อสู้",
