  str_n25_idol_y_lesson_9 = "ครัวแปลกประหลาดของ Roy",
  str_n25_idol_y_lesson_1_desc = "แสดง \"300 ข้อของคืนสีขาว\" แสงจันทราส่องหน้าเมือง...เป็นไฉน?",
  str_n25_idol_y_lesson_2_desc = "รับบท \"เจ้าหญิงอันดับ 1 แห่ง Rediesel\" ซินซาซาบซึ้งกับการแสดงจนร้องไห้...",
  str_n25_idol_y_lesson_3_desc = "แสดงเพลง \"The Courier's Song\" ฉันพนันได้เลยว่าการร้องเพลงนี้จะทำให้การคลอดของพวกเขาเร็วขึ้นมาก!",
  str_n25_idol_y_lesson_4_desc = "แสดงการเต้นบัลเลต์ เต้นด้วยนิ้วเท้าทำให้ฉันดูสูงขึ้นมาก!",
  str_n25_idol_y_lesson_5_desc = "ทำการสาธิตการยิง... แต่นั่นเกี่ยวข้องกับการเต้นจริง ๆ เหรอ?",
  str_n25_idol_y_lesson_6_desc = "ดำเนินการ Illumina Broadcast Calisthenics No. 6 ซึ่งเป็นกิจวัตรการออกกำลังกาย หนึ่งสองสามสี่! ยืดตัวลงต่ำแล้วแตะปลายเท้า!",
  str_n25_idol_y_lesson_7_desc = "สร้างประติมากรรมน้ำแข็งเป็นรูปปราสาท หิมะด้านบนทำจากน้ำตาลไอซิ่ง ดังนั้นมันจึงเริ่มละลายทันที!",
  str_n25_idol_y_lesson_8_desc = "เรียนรู้เทคนิคการแสดงต่างๆ มากมายจาก Charon เขาว่าอัจฉริยะทุกคนเหงา!",
  str_n25_idol_y_lesson_9_desc = "ทำขนมอร่อยๆ มากมายตั้งแต่เริ่มต้น... แต่ Zeta กินส่วนใหญ่ในขณะที่เราไม่ได้มองหา!",
  str_n25_idol_y_lesson_2_learn = "ต้นแบบ \"เจ้าหญิงอันดับ 1 แห่ง Rediesel\"",
  str_n25_idol_y_lesson_3_learn = "มาสเตอร์ \"The Courier's Song\"",
  str_n25_idol_y_lesson_5_learn = "ศิลปะการต่อสู้ที่เชี่ยวชาญ",
  str_n25_idol_y_lesson_6_learn = "Mastered Illumina Broadcast Calisthenics หมายเลข 6",
  str_n25_idol_y_lesson_8_learn = "เชี่ยวชาญการแสดง 108 ทักษะ",
  str_n25_idol_y_lesson_9_learn = "ฝึกฝนเทคนิคการทำอาหารของ Roy",
  str_n25_idol_y_activity_title_1 = "ปล่อยเพลงใหม่",
  str_n25_idol_y_activity_title_2 = "ปล่อยอัลบั้มรูป",
  str_n25_idol_y_activity_title_3 = "ติดดาวในละคร",
  str_n25_idol_y_activity_title_4 = "บันทึกรายการวิทยุ",
  str_n25_idol_y_activity_title_5 = "แฟนมีต",
  str_n25_idol_y_activity_title_6 = "ยิงโฆษณาสปอนเซอร์",
  str_n25_idol_y_activity_desc_1 = "<color=#6d50c3>เปิดตัวเพลงกล่อมนกฮูกลูทูมิ</color>\nฮู้ ฮู้ ♪ ดูเหมือนว่าชาวออโรเรียนจำนวนมากจะฟังเพลงนี้ก่อนนอนเพื่อให้นอนหลับสบายขึ้น",
  str_n25_idol_y_activity_desc_2 = "<color=#6d50c3>เปิดตัว \"รักชั่วฟ้าดินสลาย\"</color>\nรักบนฟ้า เฝ้ามองคุณเสมอ ♪ เนวิเกเตอร์น้ำตาไหลทันทีที่ได้ยิน!",
  str_n25_idol_y_activity_desc_3 = "<color=#6d50c3>เปิดตัว \"Chef's Sonata\"</color>\nพวกเขาใช้เครื่องครัวแทนเครื่องดนตรีในการบันทึกเพลงนี้ ดูเหมือนว่าพวกเขาจะผสมเสียง Eclipsite เล็กน้อย!",
  str_n25_idol_y_activity_desc_4 = "<color=#6d50c3>อัลบั้มภาพที่วางจำหน่าย: Fluff and Stuff!</color>\nการทำงานร่วมกันระหว่าง Goldie และ Novio กับกระต่ายของเขา กระต่ายช่างน่ารักเหลือเกิน! ใครจะไม่อยากเล่นกับสัตว์เล็ก ๆ เหล่านั้นทุกวัน?",
  str_n25_idol_y_activity_desc_5 = "<color=#6d50c3>อัลบั้มภาพที่วางจำหน่าย: Bunny Pyjamas</color>\nอัลบั้มนี้เต็มไปด้วยรูปภาพของโกลดี้ในชุดนอนกระต่ายตัวโปรดของเธอ! แม้แต่ผู้บัญชาการของ Illumina ก็ยังชอบใส่มัน!",
  str_n25_idol_y_activity_desc_6 = "<color=#6d50c3>อัลบั้มภาพเปิดตัว: Train Hard, Idol!</color>\nอัลบั้มนี้ประกอบด้วยรูปภาพที่ถ่ายของโกลดี้ระหว่างการฝึก ทุกนาทีบนเวทีต้องใช้เวลาฝึกฝนหลายปี! ไอดอลตัวจริงไม่เคยหยุดฝึกฝน!",
  str_n25_idol_y_activity_desc_7 = "<color=#6d50c3>แสดงใน: \"นักสืบกอลเมส\"</color>\nภาพยนตร์ฮิตที่นำแสดงโดยลิลิกาในบทลิลิอาร์ตี้ ผู้บงการวายร้าย และโกลดี้ในบทนักสืบกอลเมส การประลองครั้งสุดท้ายใน Umbraton นั้นน่าตื่นเต้นเป็นพิเศษ!",
  str_n25_idol_y_activity_desc_8 = "<color=#6d50c3>แสดงใน: \"Phantom of the Theatre\"</color>\nการเปิดตัว \"Phantom of the Theatre\" ประสบความสำเร็จอย่างมาก! ทุกอย่างเป็นไปด้วยดี... ยกเว้นท่อนที่โกลดี้ทำแก้วแตกพร้อมกับร้องเพลงเสียงแหลมของเธอ เดาว่าการฝึกฝนทั้งหมดนั้นได้ผลตอบแทนแล้ว!",
  str_n25_idol_y_activity_desc_9 = "<color=#6d50c3>แสดงใน: \"ห้าพันเมตรต่อวินาที\"</color>\nการแปลความหมายของ \"ห้าพันเมตรต่อวินาที\" นี้ขายหมดแล้ว! คุณสามารถเปลี่ยนเวทีให้กลายเป็นรถไฟได้ และ Charon เองก็รับบทเป็นวาทยกร!",
  str_n25_idol_y_activity_desc_10 = "<color=#6d50c3>รายการวิทยุที่บันทึกไว้: Idol Legends of Umbraton</color>\nโกลดีเล่นเป็นนักแสดงนำหญิงในรายการวิทยุ Idol Legends of Umbraton ผู้เขียนเรื่องราวไม่ประสงค์จะออกนาม แต่พวกเขาบอกว่าเป็นผู้จัดการใน Umbraton Guild",
  str_n25_idol_y_activity_desc_11 = "<color=#6d50c3>รายการวิทยุที่บันทึกไว้: Ada และ Colossus</color>\nแสดงในการผลิต Ada และ Colossus สำหรับสถานีวิทยุท้องถิ่น แม้จะสั้นแต่เรื่องราวก็ยังกินใจ นอกจากนี้เด็ก ๆ ทุกคนชอบมันมาก!",
  str_n25_idol_y_activity_desc_12 = "<color=#6d50c3>รายการวิทยุที่บันทึกไว้: รายงานการจราจรเมืองกันนอน</color>\nแขกรับเชิญในรายงานการจราจรปกติของ Gannon City ระบบขนส่งใต้ดินของเมืองนี้ซับซ้อนจริงๆ!",
  str_n25_idol_y_activity_desc_13 = "<color=#6d50c3>จัดงานแฟนมีตติ้ง: Umbraton</color>\nสายที่จะจับมือกับดาราที่รักของพวกเขาวิ่งไปตามริมฝั่งแม่น้ำทองคำ!",
  str_n25_idol_y_activity_desc_14 = "<color=#6d50c3>จัดงานแฟนมีตติ้ง: Rediesel Desert</color>\nเป็นเรื่องน่าประหลาดใจที่เห็นทุกคนใน Rediesel Wrench ต่อแถวอย่างเป็นระเบียบสำหรับงานนี้! ทุกอย่างเป็นไปได้ด้วยดีจนกระทั่งบาร์บาราขอให้ไอดอลเผชิญหน้า",
  str_n25_idol_y_activity_desc_15 = "<color=#6d50c3>จัดงานแฟนมีตติ้ง: Illumina</color>\nตอนนี้ทุกคนใน Illumina สนใจไอดอลมาก! ในงานมีผู้คนมากมาย... เห็นได้ชัดว่าแม้แต่จอมพลก็ปรากฏตัวปลอมตัวเพื่อตรวจสอบสิ่งต่างๆ!",
  str_n25_idol_y_activity_desc_16 = "<color=#6d50c3>ถ่ายภาพเสร็จ: Rediesel Delights</color>\nหลังจากถ่ายภาพโปรโมทร้าน Rediesel Delights ร้านขายขนมท้องถิ่น ร้านของ Jomu ก็แน่นขนัดมาหลายวัน!",
  str_n25_idol_y_activity_desc_17 = "<color=#6d50c3>ถ่ายรูปเสร็จ: Connolly's Cafe</color>\nผู้คนจำนวนมากอยากลองกาแฟของ Connolly หลังจากโพสต์รูปภาพโปรโมตของเรา! อันที่จริง เธอกำลังพิจารณาจ้างบาริสต้าพาร์ทไทม์...",
  str_n25_idol_y_activity_desc_18 = "<color=#6d50c3>ถ่ายภาพเสร็จสมบูรณ์: ดินแดนทางเหนือ</color>\nหลังจากถ่ายภาพเพื่อส่งเสริมการท่องเที่ยวในภาคเหนือแล้ว นักท่องเที่ยวจำนวนมากเดินทางขึ้นไปที่นั่นเพื่อปั้นตุ๊กตาหิมะและเพลิดเพลินกับสถานที่ท่องเที่ยว!",
