  str_n25_idol_y_activity_desc_short_1 = "ฮู้ ฮู้ ♪ ดูเหมือนว่าชาวออโรเรียนจำนวนมากจะฟังเพลงนี้ก่อนนอนเพื่อให้นอนหลับสบายขึ้น",
  str_n25_idol_y_activity_desc_short_2 = "รักเหนือฟ้า เฝ้ามองเธอเสมอ ♪ เนวิเกเตอร์น้ำตาไหลทันทีที่ได้ยิน!",
  str_n25_idol_y_activity_desc_short_3 = "พวกเขาใช้เครื่องครัวแทนเครื่องดนตรีในการบันทึกเพลงนี้ ดูเหมือนว่าพวกเขาจะผสมเสียง Eclipsite เล็กน้อย!",
  str_n25_idol_y_activity_desc_short_4 = "การทำงานร่วมกันระหว่าง Goldie และ Novio กับกระต่ายของเขา กระต่ายช่างน่ารักเหลือเกิน! ใครจะไม่อยากเล่นกับสัตว์เล็ก ๆ น้อย ๆ เหล่านั้นทุกวัน?",
  str_n25_idol_y_activity_desc_short_5 = "อัลบั้มนี้เต็มไปด้วยรูปภาพของโกลดี้ในชุดนอนกระต่ายตัวโปรดของเธอ! แม้แต่ผู้บัญชาการของ Illumina ก็ยังชอบใส่มัน!",
  str_n25_idol_y_activity_desc_short_6 = "อัลบั้มนี้ประกอบด้วยรูปภาพที่ถ่ายของโกลดี้ระหว่างการฝึก ทุกนาทีบนเวทีต้องใช้เวลาฝึกฝนหลายปี! ไอดอลตัวจริงไม่เคยหยุดฝึกฝน!",
  str_n25_idol_y_activity_desc_short_7 = "ภาพยนตร์ฮิตที่นำแสดงโดยลิลิกาในบทลิลิอาร์ตี้ ผู้บงการวายร้าย และโกลดี้ในบทนักสืบกอลเมส การประลองครั้งสุดท้ายใน Umbraton เป็นฉากที่น่าตื่นเต้นเป็นพิเศษ!",
  str_n25_idol_y_activity_desc_short_8 = "การเปิดตัว \"Phantom of the Theatre\" ประสบความสำเร็จอย่างมาก! ทุกอย่างเป็นไปด้วยดี... ยกเว้นท่อนที่โกลดี้ทำแก้วแตกพร้อมกับร้องเพลงเสียงแหลมของเธอ เดาว่าการฝึกฝนทั้งหมดนั้นได้ผลตอบแทนแล้ว!",
  str_n25_idol_y_activity_desc_short_9 = "การแปลความหมายของ \"ห้าพันเมตรต่อวินาที\" นี้ขายหมดแล้ว! เวทีถูกสร้างเป็นรถไฟ และ Charon เองก็รับบทเป็นวาทยกร!",
  str_n25_idol_y_activity_desc_short_10 = "โกลดีเล่นเป็นนักแสดงนำหญิงในรายการวิทยุ Idol Legends of Umbraton ผู้เขียนเรื่องราวไม่ประสงค์จะออกนาม แต่พวกเขาบอกว่าเป็นผู้จัดการใน Umbraton Guild",
  str_n25_idol_y_activity_desc_short_11 = "แสดงในการผลิต \"Ada and the Colossus\" สำหรับสถานีวิทยุท้องถิ่น แม้จะสั้นแต่เรื่องราวก็ยังกินใจ นอกจากนี้เด็ก ๆ ทุกคนชอบมันมาก!",
  str_n25_idol_y_activity_desc_short_12 = "Goldie เป็นแขกรับเชิญพิเศษในรายงานการจราจรปกติของ Gannon City ระบบขนส่งใต้ดินของเมืองนี้ซับซ้อนจริงๆ!",
  str_n25_idol_y_activity_desc_short_13 = "สายที่จะจับมือกับดาราที่รักของพวกเขาวิ่งไปตามริมฝั่งแม่น้ำทองคำ!",
  str_n25_idol_y_activity_desc_short_14 = "เป็นเรื่องน่าประหลาดใจที่เห็นทุกคนใน Rediesel Wrench ต่อแถวอย่างเป็นระเบียบสำหรับงานนี้! ทุกอย่างเป็นไปได้ด้วยดีจนกระทั่งบาร์บาราขอให้ไอดอลเผชิญหน้า",
  str_n25_idol_y_activity_desc_short_15 = "ตอนนี้ทุกคนใน Illumina สนใจไอดอลมาก! ในงานมีผู้คนมากมาย... เห็นได้ชัดว่าแม้แต่จอมพลก็ปรากฏตัวปลอมตัวเพื่อตรวจสอบสิ่งต่างๆ!",
  str_n25_idol_y_activity_desc_short_16 = "หลังจากถ่ายภาพโปรโมทร้านขายขนมในท้องถิ่นที่ชื่อว่า Rediesel Delights ผู้คนก็มารวมตัวกันที่ร้านของ Jomu มาหลายวันแล้ว!",
  str_n25_idol_y_activity_desc_short_17 = "ผู้คนจำนวนมากอยากลองกาแฟของ Connolly หลังจากโพสต์รูปภาพโปรโมตของเรา! อันที่จริง เธอกำลังพิจารณาจ้างบาริสต้าพาร์ทไทม์...",
  str_n25_idol_y_activity_desc_short_18 = "หลังจากถ่ายภาพเพื่อส่งเสริมการท่องเที่ยวในนอร์ธแลนด์แล้ว นักท่องเที่ยวจำนวนมากเดินทางขึ้นไปที่นั่นเพื่อสร้างตุ๊กตาหิมะและเพลิดเพลินไปกับสถานที่ท่องเที่ยว!",
  str_n25_idol_y_trun_closed_14 = "คอนเสิร์ตเปิดตัวประสบความสำเร็จ! The Navigator ยังคงก้าวหน้าอย่างมั่นคงบนเส้นทางสู่การเป็นผู้ผลิต\nแต่เมื่อคอนเสิร์ตเดบิวต์ใกล้จะจบลง ความท้าทายต่อไปก็ใกล้เข้ามามากขึ้น: คอนเสิร์ตประเมินผล!\nอนาคตมีไว้สำหรับพวกเขาอย่างไร? กลับมาและฝึกฝนไอดอลของคุณต่อไปเพื่อค้นหา!",
  str_n25_idol_y_trun_closed_28 = "การประกวดประเมินผลประสบความสำเร็จ! Goldie, Vice, Carleen และ Navigator ใช้เวลาสักครู่เพื่อฉลองชัยชนะที่ได้มาอย่างยากลำบาก\nสิ่งที่เหลืออยู่ตอนนี้คือความท้าทายสุดท้าย... Graduation Concert!\nอนาคตมีไว้สำหรับพวกเขาอย่างไร? กลับมาและฝึกฝนไอดอลของคุณต่อไปเพื่อค้นหา!",
