  str_n25_idol_game_puppy_question_cond_1_1 = "ไม่แน่นอน! วัดด้วยตัวคุณเองถ้าคุณไม่เชื่อฉัน!",
  str_n25_idol_game_puppy_question_cond_1_2 = "โกลดี้สูง 5'6'' จริงๆ!",
