  str_n25_idol_game_puppy_result_1_2 = "นักข่าวรับคำตอบที่ไม่น่าเชื่อของคุณและจากไป\nวันต่อมา เขาเขียนถึงการที่คุณไม่มีหลักฐาน\nแฟนๆ ของ Goldie บางคนเริ่มสงสัยในตัวเธอ",
  str_n25_idol_game_puppy_result_1_3 = "นักข่าวลงบทความเปรียบเทียบความสูงของโกลดี้กับวิก\nในนั้น Vic สูงกว่าเธออย่างชัดเจน\nนักข่าวอ้างว่าคุณพยายามเยาะเย้ยวิค\nแฟนๆ ของ Goldie บางคนเริ่มสงสัยในตัวเธอ",
